// views.js
export function renderBoard(tbody, flights, openFlight) {
  tbody.replaceChildren();
  for (const flight of flights) {
    const row = document.createElement('tr');
    const cell = document.createElement('td');
    const button = document.createElement('button');
    button.textContent = flight.id;
    button.addEventListener('click', () => openFlight(flight.id));
    cell.append(button);
    row.append(cell);
    row.insertCell().textContent = flight.terminal;
    row.insertCell().textContent = flight.scheduled;
    row.insertCell().textContent = flight.movement;
    row.insertCell().textContent = flight.stand;
    row.insertCell().textContent = flight.status;
    tbody.append(row);
  }
}

export function renderStands(container, flights) {
  container.replaceChildren();
  if (flights.length === 0) {
    container.textContent = 'No rows';
    return;
  }
  for (const flight of flights) {
    const article = document.createElement('article');
    article.className = 'assignment';
    const stand = document.createElement('strong');
    stand.textContent = flight.stand + ' · ' + flight.id;
    const interval = document.createElement('span');
    interval.textContent = flight.start + '–' + flight.end + ' UTC';
    const track = document.createElement('div');
    track.className = 'interval-track';
    track.setAttribute('aria-hidden', 'true');
    const bar = document.createElement('span');
    const minutes = value => Number(value.slice(0, 2)) * 60 + Number(value.slice(3));
    bar.style.marginLeft = ((minutes(flight.start) - 470) / 100 * 100) + '%';
    bar.style.width = ((minutes(flight.end) - minutes(flight.start)) / 100 * 100) + '%';
    track.append(bar);
    article.append(stand, interval, track);
    container.append(article);
  }
}

export function renderAlerts(container, alerts, acknowledge) {
  container.replaceChildren();
  if (alerts.length === 0) {
    container.textContent = 'No alerts';
    return;
  }
  for (const alert of alerts) {
    const article = document.createElement('article');
    article.className = 'alert';
    const title = document.createElement('strong');
    title.textContent = alert.id + ' · ' + alert.priority;
    article.append(title);
    for (const value of [alert.source, alert.message, 'Flight: ' + alert.flight]) {
      const line = document.createElement('div');
      line.textContent = value;
      article.append(line);
    }
    if (alert.ack) {
      const acknowledged = document.createElement('p');
      acknowledged.textContent = 'Acknowledged at ' + alert.ack + ' UTC';
      article.append(acknowledged);
    } else {
      const button = document.createElement('button');
      button.textContent = `Acknowledge ${alert.id}`;
      button.addEventListener('click', () => acknowledge(alert.id));
      article.append(button);
    }
    container.append(article);
  }
}

:root {
  --background: #0a0a0a;
  --heading: #00ffff;
  --border: #444444;
  --label: #ffcc00;
  --text: #ffffff;
  --text-secondary: #cccccc;
  --focus: #00ffff;
  --highlight: #ffcc00;
  --max-width: 1200px;
  --font-family: system-ui, sans-serif;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--background);
  color: var(--text);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 20px;
}

.hero {
  padding: 40px 20px;
  text-align: center;
  font-size: 2em;
  color: var(--heading);
  border-bottom: 1px solid var(--border);
}

.toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 20px 0;
  background-color: var(--background);
  padding: 10px 20px;
  border-bottom: 1px solid var(--border);
}

.metrics {
  margin: 20px 0;
  background-color: var(--background);
  padding: 15px;
  border: 1px solid var(--border);
  border-radius: 4px;
}

.panel {
  background-color: var(--background);
  padding: 15px;
  border: 1px solid var(--border);
  border-radius: 4px;
  margin-bottom: 20px;
}

.assignment {
  background-color: var(--background);
  padding: 15px;
  border: 1px solid var(--border);
  border-radius: 4px;
  margin-bottom: 20px;
}

.alert {
  background-color: var(--highlight);
  color: var(--text);
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 4px;
  margin-bottom: 10px;
}

table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 20px;
}

th {
  background-color: var(--background);
  color: var(--text);
  padding: 12px;
  text-align: left;
  border: 1px solid var(--border);
}

td {
  padding: 12px;
  border: 1px solid var(--border);
}

button {
  background-color: var(--background);
  color: var(--text);
  border: 1px solid var(--border);
  padding: 10px 16px;
  font-size: 1em;
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;
}

button:hover {
  background-color: var(--focus);
  border-color: var(--focus);
}

select {
  background-color: var(--background);
  color: var(--text);
  border: 1px solid var(--border);
  padding: 10px;
  font-size: 1em;
  width: 100%;
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
}

:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 2px var(--focus);
}

@media (max-width: 700px) {
  table {
    display: block;
    width: 100%;
  }

  table thead {
    display: none;
  }

  table tbody tr {
    display: block;
    width: 100%;
  }

  table tbody tr td {
    display: block;
    width: 100%;
    text-align: left;
  }

  table tbody tr + tr td {
    border-top: 1px solid var(--border);
  }
}
