import { fixture } from './fixture.js';
import { renderBoard, renderStands, renderAlerts } from './views.js';

const byId = id => document.getElementById(id);
const clockPattern = /^(?:[01]\d|2[0-3]):[0-5]\d$/;
const minutes = time => Number(time.slice(0, 2)) * 60 + Number(time.slice(3));
const label = 'Synthetic exercise · Non-operational';
const valid = fixture.flights.filter(flight =>
  ['T1', 'T2'].includes(flight.terminal) && clockPattern.test(flight.scheduled)
  && clockPattern.test(flight.start) && clockPattern.test(flight.end)
  && minutes(flight.start) < minutes(flight.end)
);
const controlIds = ['terminal', 'window', 'status'];
const key = 'recursa-aviation-exercise-v1';
const defaults = () => ({terminal: 'All terminals', window: 'Full exercise', status: 'All statuses',
  clock: fixture.clock_utc, paused: false, descending: false, acknowledgements: {}});
let state = defaults();
let selected = null;
let summaryOpen = false;
let visible = [];
let scopedAlerts = [];

try {
  const saved = JSON.parse(localStorage.getItem(key) || '{}');
  for (const id of controlIds) {
    if ([...byId(id).options].some(option => option.value === saved[id])) state[id] = saved[id];
  }
  if (clockPattern.test(saved.clock)) state.clock = saved.clock;
  state.paused = saved.paused === true;
  state.descending = saved.descending === true;
  for (const alert of fixture.alerts) {
    const value = saved.acknowledgements?.[alert.id];
    if (clockPattern.test(value)) state.acknowledgements[alert.id] = value;
  }
} catch {
  byId('feedback').textContent = 'Saved exercise state could not be restored.';
}

function save() {
  localStorage.setItem(key, JSON.stringify(state));
}

function scope(flight) {
  if (state.terminal !== 'All terminals' && state.terminal !== flight.terminal) return false;
  if (state.status !== 'All statuses' && state.status !== flight.status) return false;
  const time = minutes(flight.scheduled);
  return state.window === 'Full exercise' || (time >= 510 && time < 570);
}

function findConflicts(flights) {
  const conflicts = [];
  for (const [index, left] of flights.entries()) {
    for (const right of flights.slice(index + 1)) {
      if (left.stand === right.stand && minutes(left.start) < minutes(right.end)
          && minutes(right.start) < minutes(left.end)) {
        conflicts.push({stand: left.stand, flights: [left.id, right.id].sort()});
      }
    }
  }
  return conflicts;
}

function showLines(container, lines) {
  container.replaceChildren(...lines.map(value => {
    const line = document.createElement('p');
    line.textContent = value;
    return line;
  }));
}

function renderDetail() {
  const flight = visible.find(item => item.id === selected);
  const lines = flight ? [
    flight.id + ' · ' + flight.movement + ' · ' + flight.scheduled + ' UTC',
    flight.terminal + ' · Stand ' + flight.stand,
    'Milestone: ' + (flight.milestone ?? 'Unknown'),
    'Delay: ' + (flight.delay ?? 'None recorded'),
    'Alerts: ' + (scopedAlerts.filter(alert => alert.flight === flight.id).map(alert => alert.id).join(', ') || 'None')
  ] : ['Select a flight to inspect its exercise details.'];
  showLines(byId('detail-body'), lines);
}

function exportRecord() {
  return {label, clock_utc: state.clock,
    filters: {terminal: state.terminal, time_range: state.window, flight_status: state.status},
    flight_ids: visible.map(flight => flight.id), alert_ids: scopedAlerts.map(alert => alert.id),
    alert_count: scopedAlerts.length, acknowledgements: scopedAlerts.filter(alert => alert.ack)
      .map(alert => ({event_id: alert.id, exercise_utc: alert.ack}))};
}

function renderSummary() {
  const result = exportRecord();
  showLines(byId('summary-body'), [
    result.label, 'Clock: ' + result.clock_utc + ' UTC',
    'Scope: ' + Object.values(result.filters).join(' · '),
    'Flights: ' + (result.flight_ids.join(', ') || 'None'),
    'Alert IDs: ' + (result.alert_ids.join(', ') || 'None'),
    'Alerts: ' + result.alert_count, 'Acknowledged: ' + result.acknowledgements.length
  ]);
}

function render() {
  visible = valid.filter(scope).sort((left, right) =>
    (minutes(left.scheduled) - minutes(right.scheduled)) * (state.descending ? -1 : 1)
      || left.id.localeCompare(right.id));
  const ids = visible.map(flight => flight.id);
  scopedAlerts = fixture.alerts.filter(alert => ids.includes(alert.flight))
    .map(alert => ({...alert, ack: state.acknowledgements[alert.id] ?? null}));
  const conflicts = findConflicts(visible);
  byId('clock').textContent = state.clock + ' UTC · ' + (state.paused ? 'Paused' : 'Ready');
  byId('pause').textContent = state.paused ? 'Resume exercise' : 'Pause exercise';
  byId('sort').textContent = state.descending ? 'Sort earliest first' : 'Reverse schedule';
  byId('quality').textContent = 'Invalid records: ' + (fixture.flights.length - valid.length);
  byId('flight-count').textContent = 'Flights in scope: ' + visible.length;
  byId('conflict-count').textContent = 'Stand conflicts: ' + conflicts.length;
  byId('board-order').textContent = 'Board order: ' + (ids.join(', ') || 'None');
  byId('milestone-count').textContent = 'Known milestones: ' + visible.filter(flight => flight.milestone).length
    + ' · Unknown: ' + visible.filter(flight => !flight.milestone).length;
  byId('stand-minutes').textContent = 'Scheduled stand minutes: ' + visible.reduce(
    (total, flight) => total + minutes(flight.end) - minutes(flight.start), 0);
  renderBoard(byId('board').tBodies[0], visible, id => {
    selected = id;
    renderDetail();
    byId('detail').focus();
  });
  renderStands(byId('stands-body'), visible);
  showLines(byId('conflicts-body'), conflicts.length ? conflicts.map(conflict =>
    'Conflict: ' + conflict.stand + ' · ' + conflict.flights.join(' / ')) : ['No conflicts in the selected scope.']);
  renderAlerts(byId('alerts-body'), scopedAlerts, id => {
    state.acknowledgements[id] = state.clock;
    save();
    render();
    byId('alerts').focus();
  });
  renderDetail();
  if (summaryOpen) renderSummary();
}

for (const id of controlIds) {
  byId(id).value = state[id];
  byId(id).addEventListener('change', () => {
    state[id] = byId(id).value;
    save();
    render();
  });
}
byId('advance').addEventListener('click', () => {
  if (state.paused) return;
  const value = (minutes(state.clock) + 5) % 1440;
  state.clock = String(Math.floor(value / 60)).padStart(2, '0') + ':' + String(value % 60).padStart(2, '0');
  save();
  render();
});
byId('pause').addEventListener('click', () => {
  state.paused = !state.paused;
  save();
  render();
});
byId('sort').addEventListener('click', () => {
  state.descending = !state.descending;
  save();
  render();
});
byId('reset').addEventListener('click', () => {
  state = defaults();
  selected = null;
  summaryOpen = false;
  localStorage.removeItem(key);
  for (const id of controlIds) byId(id).value = state[id];
  showLines(byId('summary-body'), ['Prepare a summary for the selected scope.']);
  byId('feedback').textContent = 'Exercise reset.';
  render();
});
byId('prepare').addEventListener('click', () => {
  summaryOpen = true;
  renderSummary();
});
byId('export').addEventListener('click', () => {
  const blob = new Blob([JSON.stringify(exportRecord(), null, 2)], {type: 'application/json'});
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'synthetic-aviation-summary.json';
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
});
showLines(byId('summary-body'), ['Prepare a summary for the selected scope.']);
render();
